{
  "id": 34,
  "knowledge": "Product Release Decision Framework",
  "description": "Structured approach for determining if temperature-sensitive products can be released for use after transport.",
  "definition": "A decision framework considering: 1) Presence of temperature excursions, 2) Stability data for specific excursion profiles, 3) Package integrity, 4) Product appearance, and 5) Analytical testing results if required. Products can be 'Released' (meets all criteria), 'Released with CAPA' (meets essential criteria but requires corrective action), 'Quarantined' (requires further investigation), or 'Rejected' (failed critical criteria)."
}

{
  "id": 4,
  "knowledge": "GDP Certification Status",
  "description": "Illustrates the certification levels for carriers in Good Distribution Practice.",
  "definition": "Carriers can have one of the following certification statuses: 'None' (no certification), 'GDP' (Good Distribution Practice certified), 'CEIV Pharma' (IATA Center of Excellence for Independent Validators certification), or 'Both' (having both GDP and CEIV Pharma certifications). Null values indicate pending certification status verification."
}

{
  "id": 56,
  "knowledge": "GDP Corrective Action Categories",
  "description": "Standard categories for corrective actions in Good Distribution Practice.",
  "definition": "GDP corrective action categories include: Training Enhancement, Documentation Update, Process Modification, Equipment Upgrade, Supplier Management, Transport Adjustment, Monitoring Improvement, and Regulatory Compliance Actions."
}

{
  "id": 5,
  "knowledge": "Cold Chain Compliance Rate (CCCR)",
  "description": "Measures the percentage of shipments that maintained required temperature conditions throughout transit.",
  "definition": "CCCR = \\frac{N_{compliant}}{N_{total}} \\times 100\\%, \\text{where } N_{compliant} \\text{ is the number of shipments with zero temperature excursions, and } N_{total} \\text{ is the total number of shipments.}"
}

{
  "id": 11,
  "knowledge": "Critical Monitoring Failure",
  "description": "Indicates when monitoring systems fail to provide sufficient data to assess product quality.",
  "definition": "Occurs when either GPS completeness falls below 80% or when temperature monitoring has gaps exceeding 30 minutes during transit."
}

{
  "id": 46,
  "knowledge": "Quality Management System Maturity Model",
  "description": "Framework for assessing the sophistication of a cold chain quality management system.",
  "definition": "QMS maturity levels range from Level 1 (Basic: minimal documentation and reactive approaches) to Level 5 (Optimized: fully integrated systems with continuous improvement). Intermediate levels include Level 2 (Developing: standard procedures established), Level 3 (Defined: processes are well-documented and followed), and Level 4 (Managed: processes are measured and controlled)."
}

